package dev.arabicgames.phone;
import android.app.*;import android.os.Bundle;import android.graphics.Color;import android.graphics.drawable.GradientDrawable;import android.text.InputType;import android.view.*;import android.widget.*;import org.json.*;
/** One selected card, independent input/output percentages, numeric controls and a personal restore point. */
public final class ReadingCardsActivity extends Activity {
 static volatile boolean previewActive;
 private JSONArray cards;private int selected;private LinearLayout root,detail;private Spinner picker;private boolean loading,editingOutput;
 @Override public void onCreate(Bundle state){LiveTools.theme(this);super.onCreate(state);previewActive=true;cards=ReadingCards.load(this);root=Ui.column(this);root.setBackgroundColor(Ui.BG);root.setPadding(16,12,16,12);root.addView(Ui.text(this,"مناطق القراءة والبطاقات",23));
  picker=new Spinner(this);refreshPicker();root.addView(picker);picker.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> a){}public void onItemSelected(android.widget.AdapterView<?> a,View v,int i,long id){if(selected!=i)editingOutput=false;selected=i;render();}});
  detail=Ui.column(this);root.addView(detail);render();ScrollView scroll=new ScrollView(this);scroll.addView(root);PhoneInsets.fit(scroll);setContentView(scroll);
 }
 private JSONObject card(){return cards.optJSONObject(Math.min(selected,Math.max(0,cards.length()-1)));}
 private void refreshPicker(){String[] labels=new String[cards.length()];for(int i=0;i<labels.length;i++)labels[i]=(i+1)+" · "+cards.optJSONObject(i).optString("name");picker.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,labels){@Override public View getView(int position,View convert,ViewGroup parent){View view=super.getView(position,convert,parent);if(view instanceof TextView)((TextView)view).setTextColor(ReadingCards.COLORS[position%ReadingCards.COLORS.length]);return view;}});picker.setSelection(Math.min(selected,cards.length()-1));}
 private void render(){if(detail==null||card()==null)return;loading=true;detail.removeAllViews();JSONObject c=card();int color=ReadingCards.COLORS[selected%ReadingCards.COLORS.length];GradientDrawable border=Ui.background(this,Ui.CARD);border.setStroke(Ui.dp(this,2),color);detail.setBackground(border);detail.setPadding(12,12,12,12);
  TextView name=Ui.text(this,"البطاقة المحددة: "+c.optString("name"),18);name.setTextColor(color);detail.addView(name);Switch enabled=new Switch(this);enabled.setText("تفعيل هذه البطاقة فقط");enabled.setTextColor(Ui.TEXT);enabled.setChecked(c.optBoolean("enabled"));enabled.setEnabled(!"dialogue".equals(c.optString("kind")));enabled.setOnCheckedChangeListener((b,on)->put(c,"enabled",on));detail.addView(enabled);
  CardPreview preview=new CardPreview(this,c,color,this::render);preview.output=editingOutput;LinearLayout targets=new LinearLayout(this);Ui.button(this,targets,"تعديل القراءة",false,()->{editingOutput=false;preview.output=false;preview.invalidate();}).setLayoutParams(new LinearLayout.LayoutParams(0,-2,1));Ui.button(this,targets,"تعديل الظهور",false,()->{editingOutput=true;preview.output=true;preview.invalidate();}).setLayoutParams(new LinearLayout.LayoutParams(0,-2,1));detail.addView(targets);detail.addView(preview);detail.addView(Ui.text(this,"اسحب المربع المحدد أو زاويته؛ اللون ثابت للبطاقة ولا يغيّر بطاقات أخرى.",12));
  geometry(c,"source","① من أين نقرأ؟ · النسب المئوية");geometry(c,"output","② أين تظهر الترجمة؟ · النسب المئوية");
  Spinner fonts=new Spinner(this);String[] fontIds={"noto","tajawal","cairo","changa","lalezar"};fonts.setAdapter(new ArrayAdapter<String>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"Noto Sans Arabic · متوسط","Tajawal · واضح","Cairo","Changa","Lalezar"}));int choice=java.util.Arrays.asList(fontIds).indexOf(c.optString("font","noto"));fonts.setSelection(Math.max(0,choice));fonts.setOnItemSelectedListener(new android.widget.AdapterView.OnItemSelectedListener(){public void onNothingSelected(android.widget.AdapterView<?> p){}public void onItemSelected(android.widget.AdapterView<?> p,View v,int i,long id){put(c,"font",fontIds[i]);}});detail.addView(Ui.text(this,"خط البطاقة",16));detail.addView(fonts);
  number(detail,"حجم الخط",c.optInt("fontSize",28),14,48,1,v->put(c,"fontSize",v));number(detail,"عتامة الخلفية %",c.optInt("background",72),0,100,5,v->put(c,"background",v));number(detail,"فاصل قراءة البطاقة · ms",c.optInt("intervalMs",450),100,2000,50,v->put(c,"intervalMs",v));
  if("phone".equals(c.optString("kind"))){Switch style=new Switch(this);style.setText("فقاعات عائمة فقط · إيقافه يعرض لوحة المحادثة");style.setTextColor(Ui.TEXT);style.setChecked("floating".equals(c.optString("phoneStyle")));style.setOnCheckedChangeListener((b,on)->put(c,"phoneStyle",on?"floating":"panel"));detail.addView(style);}
  Ui.button(this,detail,"حفظ وتطبيق — البث مستمر",true,()->{ReadingCards.save(this,cards);Status.message="حُفظت بطاقات القراءة ومواضع العرض.";});
  Ui.button(this,detail,"استعادة إعداداتي الأساسية لهذه البطاقة",false,()->{JSONObject saved=ReadingCards.restore(this,c.optString("id"));if(saved!=null){try{cards.put(selected,saved);}catch(JSONException ignored){}render();ReadingCards.save(this,cards);}});
  Ui.button(this,detail,"اعتماد الإعدادات الحالية كأساسية",false,()->{ReadingCards.save(this,cards);ReadingCards.baseline(this,cards);Toast.makeText(this,"حُفظت إعداداتك الحالية للاستعادة",Toast.LENGTH_SHORT).show();});
  if(!"dialogue".equals(c.optString("kind")))Ui.button(this,detail,"حذف البطاقة المحددة",false,()->{cards.remove(selected);selected=Math.max(0,selected-1);refreshPicker();render();ReadingCards.save(this,cards);});
  Ui.button(this,detail,"إضافة بطاقة من القوالب",false,()->{try{JSONArray defaults=ReadingCards.defaults(this);String[] names=new String[defaults.length()-1];for(int i=1;i<defaults.length();i++)names[i-1]=defaults.getJSONObject(i).getString("name");new AlertDialog.Builder(this).setTitle("قوالب دون تكرار البطاقات").setItems(names,(d,i)->{try{JSONObject chosen=defaults.getJSONObject(i+1);for(int n=0;n<cards.length();n++)if(chosen.getString("id").equals(cards.getJSONObject(n).optString("id"))){selected=n;refreshPicker();render();return;}cards.put(chosen);selected=cards.length()-1;refreshPicker();render();}catch(JSONException ignored){}}).show();}catch(JSONException ignored){}});
  Ui.button(this,detail,"رجوع للبث",false,this::finish);loading=false;
 }
 private void geometry(JSONObject c,String key,String title){detail.addView(Ui.text(this,title,17));float[] b=ReadingCards.bounds(c,key);String[] labels={"اليسار %","الأعلى %","العرض %","الارتفاع %"};for(int i=0;i<4;i++){final int index=i;numeric(detail,labels[i],b[i]*100,i<2?0:3,i<2?97:100,.1,true,value->{float[] current=ReadingCards.bounds(c,key);current[index]=(float)(value/100);current[0]=Math.max(0,Math.min(current[0],1-current[2]));current[1]=Math.max(0,Math.min(current[1],1-current[3]));try{c.put(key,ReadingCards.box(current[0],current[1],current[0]+current[2],current[1]+current[3]));}catch(JSONException ignored){}});}}
 interface Value{void apply(int value);}
 static EditText number(LinearLayout root,String title,int initial,int min,int max,int step,Value changed){return numeric(root,title,initial,min,max,step,false,v->changed.apply((int)Math.round(v)));}
 private static double parse(String text){StringBuilder value=new StringBuilder();for(char c:text.trim().toCharArray())value.append(Character.isDigit(c)?(char)('0'+Character.getNumericValue(c)):c=='٫'||c==','?'.':c);return Double.parseDouble(value.toString());}
 private static String format(double n,boolean decimal){return String.format(java.util.Locale.ROOT,decimal?"%.1f":"%.0f",n);}
 static EditText numeric(LinearLayout root,String title,double initial,double min,double max,double step,boolean decimal,java.util.function.DoubleConsumer changed){Activity a=(Activity)root.getContext();root.addView(Ui.text(a,title,14));LinearLayout row=new LinearLayout(a);EditText value=new EditText(a);value.setContentDescription(title);value.setTextColor(Ui.TEXT);value.setSingleLine();value.setGravity(Gravity.CENTER);value.setInputType(InputType.TYPE_CLASS_NUMBER|(decimal?InputType.TYPE_NUMBER_FLAG_DECIMAL:0));value.setText(format(initial,decimal));Runnable commit=()->{try{double n=Math.max(min,Math.min(max,parse(value.getText().toString())));if(!Double.isFinite(n))throw new NumberFormatException();value.setText(format(n,decimal));changed.accept(n);}catch(NumberFormatException e){value.setText(format(initial,decimal));}};
  Button minus=new Button(a),plus=new Button(a);minus.setText("−");plus.setText("+");minus.setOnClickListener(v->{try{value.setText(format(Math.max(min,parse(value.getText().toString())-step),decimal));commit.run();}catch(NumberFormatException e){commit.run();}});plus.setOnClickListener(v->{try{value.setText(format(Math.min(max,parse(value.getText().toString())+step),decimal));commit.run();}catch(NumberFormatException e){commit.run();}});
  value.addTextChangedListener(new android.text.TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence text,int start,int before,int count){try{double n=parse(text.toString());if(Double.isFinite(n)&&n>=min&&n<=max)changed.accept(n);}catch(NumberFormatException ignored){}}public void afterTextChanged(android.text.Editable e){}});value.setOnFocusChangeListener((v,focus)->{if(!focus)commit.run();});row.addView(minus,new LinearLayout.LayoutParams(Ui.dp(a,52),Ui.dp(a,48)));row.addView(value,new LinearLayout.LayoutParams(0,Ui.dp(a,48),1));row.addView(plus,new LinearLayout.LayoutParams(Ui.dp(a,52),Ui.dp(a,48)));root.addView(row);return value;
 }
 @Override public void onDestroy(){previewActive=false;super.onDestroy();}
 private void put(JSONObject object,String key,Object value){if(loading)return;try{object.put(key,value);}catch(JSONException ignored){}}
}
